import {renderFormula,enterFormula} from './formula.js';
import {RankingClient,SubmissionQueue} from './ranking-client.js';
import {seeded} from './engine.js';
import {Game} from './engine.js';
import {load,record,loadSound,saveSound} from './storage.js';
const app=document.querySelector('#app');let difficulty='NORMAL',game=null,screen='title',saved=null;
const rankingClient=new RankingClient(window.HIGHLOW_RANKING_CONFIG||{});let onlineRun=null,onlineMessage='',rankDifficulty='NORMAL',rankPeriod='daily',rankRequest=0;
const outbox=new SubmissionQueue(rankingClient);let startGen=0,waitTimer=null,prefetch=null,view={},noteTimer=null,exitTimer=null,resultsTimer=null,resultRunId=null;const PREFETCH_MAX_AGE=40000,NOTE_MS=1000,sound={on:loadSound(),ctx:null};
const head=()=>`<header><span>HIGH<span style="color:var(--gold)">×</span>LOW</span><span class="header-right"><span class="version"><i class="status"></i>SOLO ARCADE · VER.1.0 · TEST</span><button class="sound-toggle" id="sound-toggle" type="button" aria-pressed="${sound.on}" aria-label="効果音">${sound.on?'♪ ON':'♪ OFF'}</button></span></header>`;
function setTheme(value){document.body.dataset.difficulty=value.toLowerCase()}
const fmt=n=>Math.round(n).toLocaleString('ja-JP');
function title(){setTheme(difficulty);screen='title';game=null;app.innerHTML=head()+`<div class="outbox" id="outbox" hidden></div><section class="title"><div class="eyebrow title-badge">ひらめき×30秒</div><div class="title-art"><div class="hero-doodles" aria-hidden="true"><span>＋</span><span>÷</span><span>＝</span><span>√</span></div><h1 class="logo logo--image"><img class="title-logo" src="assets/title-logo.png" alt="HIGH×LOW" width="2172" height="724" fetchpriority="high" decoding="async"></h1></div><p class="tagline">大きいのは、どっち？ 比べて、ひらめけ！</p><div class="demo" aria-hidden="true"><div><small>LEFT</small><span class="formula" id="demo-left"></span></div><span>VS</span><div><small>RIGHT</small><span class="formula" id="demo-right"></span></div></div><div class="section-label">難易度をえらぼう <span>SELECT LEVEL</span></div><div class="difficulties">${['EASY','NORMAL','HARD'].map((d,i)=>`<button class="difficulty ${d===difficulty?'selected':''}" data-difficulty="${d}" aria-pressed="${d===difficulty}"><span class="level-dots" aria-hidden="true">${['●','●●','●●●'][i]}</span><strong>${d}</strong><small>${['四則演算 / 2択','四則演算 / 3択','高校数学 / 3択'][i]}</small></button>`).join('')}</div><p class="best">PERSONAL BEST <b>${fmt(load().records[difficulty]?.best||0)}</b></p><div class="title-actions"><button class="primary" id="play">PLAY <span>↗</span></button><button class="secondary" id="ranking">RANKING</button></div><p class="hint">← 左が大きい　 ↓ 同じ　 → 右が大きい${difficulty==='EASY'?'（↓は使用しません）':''}</p><details><summary>遊び方・ルール <span>HOW TO PLAY</span></summary><p>左右の式を比べて、大きい方をタップ。同じ値なら EQUAL。EASYは左右の2択です。<br>考える時間は30秒。正解で100点、5連続で120点、10連続で150点、20連続で200点。誤答は−100点でコンボが0に戻ります。<br>正誤表示の0.3秒は制限時間に含みません。別タブや別アプリに移動すると中断し、記録は保存されません。三角関数の角度は度数法（°）です。</p></details></section><footer>THINK FAST. AIM HIGH.</footer>`;renderFormula(document.querySelector('#demo-left'),'8 × 7');renderFormula(document.querySelector('#demo-right'),'63 − 9');app.querySelectorAll('[data-difficulty]').forEach(b=>b.onclick=()=>{difficulty=b.dataset.difficulty;if(prefetch&&prefetch.difficulty!==difficulty)prefetch=null;title()});document.querySelector('#play').onclick=start;document.querySelector('#ranking').onclick=()=>showRanking();renderOutbox();if(rankingClient.available)rankingClient.identity().catch(()=>{})}
async function start(){if(screen==='connecting')return;const gen=++startGen;setTheme(difficulty);saved=null;onlineRun=null;onlineMessage='';screen='connecting';app.innerHTML=head()+'<section class="results connecting"><p role="status">試合を準備しています…</p><div class="connect-actions" id="connect-actions" hidden><button class="primary" id="play-offline">ランキングなしで遊ぶ</button><button class="secondary" id="connect-back">戻る</button></div></section>';clearTimeout(waitTimer);waitTimer=setTimeout(()=>{const a=document.querySelector('#connect-actions');if(gen===startGen&&screen==='connecting'&&a)a.hidden=false},2000);document.querySelector('#play-offline').onclick=()=>{if(gen!==startGen||screen!=='connecting')return;startGen++;clearTimeout(waitTimer);onlineRun=null;onlineMessage='ランキングなしで遊んでいます。今回はランキング対象外です。';launch()};document.querySelector('#connect-back').onclick=()=>{startGen++;clearTimeout(waitTimer);title()};let run=null,message='';try{run=await obtainRun(difficulty)}catch(e){message=e.message+' 今回はランキング対象外です。'}if(gen!==startGen||screen!=='connecting')return;clearTimeout(waitTimer);onlineRun=run;onlineMessage=message;if(document.hidden){onlineRun=null;title();return}launch()}
function launch(){view={};clearTimeout(noteTimer);clearTimeout(exitTimer);screen='game';game=new Game(difficulty,onlineRun?{rng:seeded(onlineRun.seed)}:{});game.start();app.innerHTML=head()+`<section class="game"><div class="game-top"><span class="pill">${difficulty} / SOLO</span><button class="quiet" id="exit">中断する ×</button></div><div class="stats"><div><small>TIME LEFT</small><strong id="time">30.0</strong></div><div><small>SCORE</small><strong class="gold" id="score">0</strong></div><div><small>COMBO</small><strong id="combo">0</strong></div></div><div class="timer-bar"><i id="bar"></i></div><p class="online-mode" id="online-mode"></p><p class="prompt">大きい方を選べ${difficulty==='EASY'?'':'。同じなら EQUAL'}</p><div class="arena"><button class="card" id="left" aria-label="LEFT 左が大きい"><span class="side">LEFT</span><span class="formula" id="lf"></span><kbd>←</kbd></button><span class="versus" id="versus">VS</span><button class="card right" id="right" aria-label="RIGHT 右が大きい"><span class="side">RIGHT</span><span class="formula" id="rf"></span><kbd>→</kbd></button></div>${difficulty==='EASY'?'':'<button class="equal" id="equal"><span>＝</span>EQUAL <small>↓</small></button>'}<div class="feedback-zone"><div class="feedback" id="feedback" role="status"></div><div class="answer-note" id="answer-note" aria-live="polite"></div></div><footer>TRUST YOUR NUMBERS.</footer></section><div class="countdown" id="countdown"><span>GET READY</span><b>3</b><span>大きい数式をタップ</span></div>`;['LEFT','RIGHT','EQUAL'].forEach(c=>{const b=document.getElementById(c.toLowerCase());if(b){b.onclick=()=>answer(c);pressable(b)}});document.querySelector('#exit').onclick=armExit;document.querySelector('#online-mode').textContent=onlineRun?'オンライン記録対象':onlineMessage;render()}
function answer(c){if(game&&screen==='game'){game.answer(c);try{render()}catch(e){crash(e)}}}
function render(){if(screen!=='game')return;if(game.state==='FINISHED'){results();return}const countdown=document.querySelector('#countdown'),inCountdown=game.state==='COUNTDOWN';if(inCountdown)put('countdown',countdown.querySelector('b'),'textContent',String(Math.max(1,Math.ceil((game.until-performance.now())/1000))));put('countdownShow',countdown.style,'display',inCountdown?'flex':'none');const left=game.timeLeft();put('time',document.querySelector('#time'),'textContent',(left/1000).toFixed(1));document.querySelector('#bar').style.transform=`scaleX(${left/30000})`;const hurry=left<=5000&&left>0&&(game.state==='PLAYING'||game.state==='FEEDBACK');if(view.hurry!==hurry){view.hurry=hurry;document.querySelector('.game').classList.toggle('hurry',hurry)}const second=Math.ceil(left/1000);if(hurry&&view.second!==second)restart(document.querySelector('#time'),'pulse');view.second=second;put('score',document.querySelector('#score'),'textContent',fmt(game.score));put('combo',document.querySelector('#combo'),'textContent',String(game.combo));const locked=game.state!=='PLAYING';['LEFT','RIGHT','EQUAL'].forEach(c=>{const b=document.getElementById(c.toLowerCase());if(b)put('disabled-'+c,b,'disabled',locked)});if(game.question&&game.question.id!==view.question){view.question=game.question.id;const lf=document.querySelector('#lf'),rf=document.querySelector('#rf');renderFormula(lf,game.question.leftExpression);renderFormula(rf,game.question.rightExpression);enterFormula(lf);enterFormula(rf)}if(game.history.length!==(view.answered??0)){view.answered=game.history.length;showAnswer(game.history[game.history.length-1],game.history[game.history.length-2])}if(view.state!==game.state){const was=view.state;view.state=game.state;if(was==='FEEDBACK')clearAnswer()}}
function results(){screen='results';clearTimeout(noteTimer);clearTimeout(exitTimer);const s=game.stats();saved=game.interrupted?{saved:false,isBest:false}:record(difficulty,game);const run=!game.interrupted&&onlineRun?onlineRun:null;resultRunId=run?run.runId:null;app.innerHTML=head()+`<section class="results enter"><span class="eyebrow">${difficulty} / SOLO RESULT</span><h1>${game.interrupted?'SESSION INTERRUPTED':'TIME UP. WELL PLAYED.'}</h1>${game.interrupted?`<p class="interrupted">${game.crashed?'エラーが発生したため中断しました。記録は保存されません。':'プレイを中断しました。記録は保存されません。'}</p>`:''}<div class="final-score">${fmt(s.score)}</div><div class="eyebrow">TOTAL SCORE</div><div class="record">${saved.isBest?'★ NEW PERSONAL BEST':'次の30秒で、自分を超えよう。'}</div><div class="result-grid">${[['CORRECT / 正解',s.correct],['MISS / 誤答',s.wrong],['ACCURACY / 正答率',s.accuracy.toFixed(1)+'%'],['MAX COMBO',s.maxCombo],['AVG TIME / 平均', (s.average/1000).toFixed(2)+'s'],['DIFFICULTY',difficulty]].map(([l,v])=>`<div><small>${l}</small><b>${v}</b></div>`).join('')}</div>${!saved.saved&&!game.interrupted?`<p class="save-note">${saved.reason==='future-version'?'新しいバージョンの記録があるため、この端末の記録は更新していません。ページを再読み込みしてください。':saved.reason==='read-error'?'保存済みの記録を読み取れなかったため、上書きせずに保存を中止しました。ブラウザの保存設定をご確認ください。':'保存できませんでした。ブラウザの保存設定をご確認ください。'}</p>`:''}<div class="online-result" id="online-result" role="status"></div><div class="result-actions"><div class="result-sub"><button class="secondary" id="result-ranking" data-lock disabled>RANKING</button><button class="secondary" id="title" data-lock disabled>TITLE</button></div><button class="primary retry" id="retry" data-lock disabled>RETRY ↻</button></div></section>`;document.querySelector('#retry').onclick=start;document.querySelector('#title').onclick=title;document.querySelector('#result-ranking').onclick=()=>showRanking();clearTimeout(resultsTimer);resultsTimer=setTimeout(()=>{if(screen==='results')app.querySelectorAll('[data-lock]').forEach(b=>b.disabled=false)},500);if(run)syncResult(game,run);else document.querySelector('#online-result').textContent=game.interrupted?'ランキングには登録されません。':onlineMessage;prefetchNext()}
document.addEventListener('keydown',e=>{if(screen!=='game'||e.repeat)return;const c={ArrowLeft:'LEFT',ArrowRight:'RIGHT',ArrowDown:'EQUAL'}[e.key];if(c){e.preventDefault();const b=document.getElementById(c.toLowerCase());if(b&&!b.disabled)flashPress(b);answer(c)}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&screen==='game'){game.interrupt();results()}});window.addEventListener('pagehide',()=>{if(game&&screen==='game')game.interrupt()});function loop(){requestAnimationFrame(loop);if(game&&screen==='game'){try{game.tick();render()}catch(e){crash(e)}}}title();requestAnimationFrame(loop);
async function syncResult(completedGame,run){const answers=completedGame.history.map(a=>({questionId:a.question.id,choice:a.choice,elapsed:a.elapsed}));await outbox.add({runId:run.runId,difficulty:completedGame.difficulty,score:completedGame.score,answers})}
async function showRanking(){setTheme(rankDifficulty);screen='ranking';const current=++rankRequest;app.innerHTML=head()+`<div class="outbox" id="outbox" hidden></div><section class="rankings"><div class="game-top"><h1>RANKING</h1><button class="quiet" id="rank-title">TITLE</button></div><p class="ranking-note">日本時間で集計・週間は月曜0時から。得点 → 正答率 → 平均回答時間の順。完全同点は同順位です。</p><form id="nickname-form"><label for="nickname">ニックネーム（1〜16文字）</label><div class="name-input"><input id="nickname" name="nickname" maxlength="16" autocomplete="nickname" placeholder="ニックネームを登録"><button class="secondary" type="submit">登録</button></div><p id="name-status" role="status"></p></form><div class="rank-filters"><label>難易度<select id="rank-difficulty">${['EASY','NORMAL','HARD'].map(d=>`<option ${d===rankDifficulty?'selected':''}>${d}</option>`).join('')}</select></label><label>集計期間<select id="rank-period">${[['daily','デイリー'],['weekly','週間'],['all','歴代']].map(([v,l])=>`<option value="${v}" ${v===rankPeriod?'selected':''}>${l}</option>`).join('')}</select></label></div><div id="rank-me" class="my-rank"></div><p id="rank-period-label" class="ranking-note"></p><div id="rank-status" role="status">ランキングを読み込んでいます…</div><div class="ranking-table-wrap"><table class="ranking-table"><thead><tr><th scope="col">順位</th><th scope="col">プレイヤー</th><th scope="col">得点</th><th scope="col">正答率</th><th scope="col">平均</th></tr></thead><tbody id="rank-rows"></tbody></table></div><button class="secondary" id="rank-refresh">更新</button><p class="ranking-note">このブラウザの識別情報を使用します。保存情報を削除すると別プレイヤーになります。</p></section>`;document.querySelector('#rank-title').onclick=title;document.querySelector('#rank-difficulty').onchange=e=>{rankDifficulty=e.target.value;showRanking()};document.querySelector('#rank-period').onchange=e=>{rankPeriod=e.target.value;showRanking()};document.querySelector('#rank-refresh').onclick=()=>showRanking();renderOutbox();const nameInput=document.querySelector('#nickname');nameInput.value=rankingClient.profile?.player.nickname||'';document.querySelector('#nickname-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;const status=document.querySelector('#name-status');try{await rankingClient.identity();await rankingClient.nickname(nameInput.value);if(screen==='ranking'&&current===rankRequest){const next=showRanking(),notice=document.querySelector('#name-status');if(notice){notice.textContent='登録しました';setTimeout(()=>{if(notice.isConnected&&notice.textContent==='登録しました')notice.textContent=''},1500)}await next}}catch(error){if(screen==='ranking'&&current===rankRequest)status.textContent=error.message}finally{button.disabled=false}};
 try{const data=await rankingClient.ranking(rankDifficulty,rankPeriod);if(screen!=='ranking'||current!==rankRequest)return;nameInput.value=rankingClient.profile?.player.nickname||'';document.querySelector('#rank-status').textContent=data.rows.length?'上位100名を表示しています。':'まだ記録がありません。最初の記録を残そう。';document.querySelector('#rank-period-label').textContent=data.period==='all'?'歴代の最高記録':(data.period==='weekly'?'週の開始日：':'対象日：')+data.periodKey+'（日本時間）';document.querySelector('#rank-me').textContent=data.me?`あなた：${data.me.rank}位 / ${data.totalPlayers}名　最高 ${fmt(data.me.score)}点`:'あなた：この期間の掲載記録はまだありません。ニックネーム登録と試合完走で掲載されます。';const tbody=document.querySelector('#rank-rows');for(const row of data.rows){const tr=document.createElement('tr');if(row.isMe)tr.className='is-me';for(const text of [String(row.rank),row.nickname,fmt(row.score),row.accuracy.toFixed(1)+'%',row.averageMs===null?'—':(row.averageMs/1000).toFixed(2)+'s']){const td=document.createElement('td');td.textContent=text;tr.append(td)}tbody.append(tr)}}catch(e){if(screen==='ranking'&&current===rankRequest)document.querySelector('#rank-status').textContent=e.message}}
// --- Stage 1 (client-only) helpers: diffed DOM writes, answer feedback, press state, sound, run prefetch, submission outbox ---
function put(key,el,prop,value){if(view[key]===value)return;view[key]=value;el[prop]=value}
function restart(el,cls){if(!el)return;el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls)}
function deltaLabel(d){return d>0?'+'+d:d<0?'−'+(-d):'±0'}
function showAnswer(h,prev){if(!h)return;const delta=h.score-(prev?prev.score:0),correct=h.choice===h.question.answer,chosen=document.getElementById(h.choice.toLowerCase()),relation={LEFT:'＞',RIGHT:'＜',EQUAL:'＝'}[h.question.answer];for(const b of document.querySelectorAll('.arena .card,.game .equal'))b.classList.remove('pick-good','pick-bad','is-answer');if(chosen){restart(chosen,correct?'pick-good':'pick-bad');const f=document.createElement('span');f.className='score-float '+(delta>0?'plus':delta<0?'minus':'zero');f.textContent=deltaLabel(delta);f.setAttribute('aria-hidden','true');chosen.append(f);const drop=()=>f.remove();f.addEventListener('animationend',drop);setTimeout(drop,700)}if(!correct){const a=document.getElementById(h.question.answer.toLowerCase());if(a)a.classList.add('is-answer')}const v=document.querySelector('#versus');if(v){v.textContent=relation;v.classList.add('relation')}const fb=document.querySelector('#feedback');if(fb){fb.className='feedback '+(correct?'good':'bad');fb.textContent=(correct?'✓ CORRECT　':'✕ MISS　')+deltaLabel(delta)}const note=document.querySelector('#answer-note');clearTimeout(noteTimer);if(note){if(correct){note.className='answer-note';note.textContent=''}else{note.className='answer-note show';note.textContent='正解：LEFT '+relation+' RIGHT';noteTimer=setTimeout(()=>{if(note.isConnected)note.className='answer-note'},NOTE_MS)}}playSound(correct,game.combo)}
function clearAnswer(){for(const b of document.querySelectorAll('.arena .card,.game .equal'))b.classList.remove('pick-good','pick-bad','is-answer');const v=document.querySelector('#versus');if(v){v.textContent='VS';v.classList.remove('relation')}const fb=document.querySelector('#feedback');if(fb){fb.className='feedback';fb.textContent=''}const note=document.querySelector('#answer-note');if(note&&note.classList.contains('show'))note.classList.add('stale')}
function pressable(b){const release=()=>b.classList.remove('is-pressed');b.addEventListener('pointerdown',e=>{if(e.isPrimary===false||e.button>0)return;b.classList.add('is-pressed')});for(const type of ['pointerup','pointercancel','pointerleave','lostpointercapture','touchend','touchcancel'])b.addEventListener(type,release,{passive:true})}
function flashPress(b){b.classList.add('is-pressed');setTimeout(()=>b.classList.remove('is-pressed'),60)}
function armExit(){const b=document.querySelector('#exit');if(!b||!game||screen!=='game')return;if(b.dataset.armed==='1'){clearTimeout(exitTimer);game.interrupt();results();return}b.dataset.armed='1';b.classList.add('armed');b.textContent='もう一度押すと中断';clearTimeout(exitTimer);exitTimer=setTimeout(()=>{if(b.isConnected){b.dataset.armed='';b.classList.remove('armed');b.textContent='中断する ×'}},2000)}
function crash(e){console.error('HIGH×LOW: unexpected error',e);try{if(game&&screen==='game'){if(game.state!=='FINISHED')game.interrupt();game.interrupted=true;game.crashed=true;results()}}catch(again){console.error(again);try{title()}catch{}}}
// A prefetched run must be used soon: the server rejects results that arrive >60s after the expected end of the run.
async function obtainRun(d){const p=prefetch;prefetch=null;if(p&&p.difficulty===d&&Date.now()-p.at<PREFETCH_MAX_AGE){try{const run=await p.promise;if(Date.now()-p.at<PREFETCH_MAX_AGE)return run}catch{}}return rankingClient.start(d)}
function prefetchNext(){if(!rankingClient.available||document.hidden)return;const d=difficulty,promise=rankingClient.start(d);promise.catch(()=>{});prefetch={difficulty:d,at:Date.now(),promise}}
function renderOutbox(){const box=document.querySelector('#outbox');if(!box)return;const list=outbox.pending();box.hidden=!list.length;box.replaceChildren();if(!list.length)return;const head=document.createElement('p');head.className='outbox-title';head.textContent=`未送信の記録が${list.length}件あります`;box.append(head);for(const e of list.slice(0,3)){const row=document.createElement('div');row.className='outbox-row';const text=document.createElement('span');text.textContent=`${e.difficulty} ${fmt(e.score)}点：${e.status==='sending'?'送信中…':e.message||'送信できませんでした。'}`;row.append(text);if(e.status!=='sending'){const b=document.createElement('button');b.type='button';b.className='quiet';b.textContent=e.status==='rejected'?'閉じる':'再送信';b.onclick=()=>e.status==='rejected'?outbox.dismiss(e.runId):outbox.retry(e.runId);row.append(b)}box.append(row)}}
function renderResultStatus(e){const target=document.querySelector('#online-result');if(screen!=='results'||!target||!e||e.runId!==resultRunId)return;target.replaceChildren();if(e.status==='sending'){target.textContent='ランキングに記録を送信しています…';return}if(e.status==='done'){target.textContent=e.response?.registered?'✓ 記録を登録しました。各期間の最高記録を確認し、更新分を反映しました。':'✓ 記録を保存しました。RANKINGでニックネームを登録すると掲載されます。';return}target.textContent=e.message+' ';const b=document.createElement('button');b.type='button';b.className='quiet';b.textContent=e.status==='rejected'?'閉じる':'再送信';b.onclick=()=>{if(e.status==='rejected'){outbox.dismiss(e.runId);target.textContent='この記録はランキングに登録されませんでした。'}else outbox.retry(e.runId)};target.append(b)}
function audio(){if(!sound.on)return null;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;if(!sound.ctx)sound.ctx=new AC();if(sound.ctx.state==='suspended')sound.ctx.resume().catch(()=>{});return sound.ctx.state==='closed'?null:sound.ctx}catch{return null}}
function tone(from,to,ms,{type='sine',delay=0,volume=.16}={}){const ctx=audio();if(!ctx)return;try{const t=ctx.currentTime+delay/1000,end=t+ms/1000,o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(from,t);if(to!==from)o.frequency.exponentialRampToValueAtTime(to,end);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(volume,t+.005);g.gain.setValueAtTime(volume,Math.max(t+.005,end-.015));g.gain.exponentialRampToValueAtTime(.0001,end);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(end+.02)}catch{}}
function playSound(correct,combo){if(!sound.on)return;if(correct){tone(880,1320,60);if(combo===5||combo===10||combo===20)tone(660,combo===20?1980:combo===10?1760:1320,150,{type:'triangle',delay:70,volume:.13})}else tone(200,200,120,{type:'square',volume:.07})}
function unlockAudio(){if(sound.on)audio()}
['pointerdown','touchend','click','keydown'].forEach(type=>document.addEventListener(type,unlockAudio,{capture:true,passive:true}));
document.addEventListener('click',e=>{const b=e.target.closest?.('#sound-toggle');if(!b)return;sound.on=!sound.on;saveSound(sound.on);b.setAttribute('aria-pressed',String(sound.on));b.textContent=sound.on?'♪ ON':'♪ OFF';if(sound.on)tone(880,1320,60)});
window.addEventListener('blur',()=>document.querySelectorAll('.is-pressed').forEach(x=>x.classList.remove('is-pressed')));
outbox.subscribe(e=>{renderOutbox();renderResultStatus(e)});
